&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Chef de clan troglodyte &lt;div style=&quot;float:right;&quot;&gt;FP 8&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Humano&#239;de&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Humano&#239;de.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Souterrain&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Souterrain.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Codex Monstrueux p.217&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 4800
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Troglodyte.html&quot; title=&quot;Troglodyte&quot;&gt;Troglodyte&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; 2/&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; (druide des cavernes) 6 (&lt;i&gt;Manuel des
Joueurs, r&#232;gles avanc&#233;es&lt;/i&gt; p. 87)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Reptilien.html&quot; title=&quot;Reptilien (sous-type)&quot;&gt;reptilien&lt;/a&gt;) de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +4 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 27 m (18 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur&quot;&gt;puanteur&lt;/a&gt; (9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), DD 14, 10 rounds)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 21, contact 11, pris au d&#233;pourvu 21 (+4 armure, +9 naturelle, -2 rage)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 100 (10 DV ; 8d8+2d12+46)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +4, &lt;b&gt;Vig&lt;/b&gt; +14, &lt;b&gt;Vol&lt;/b&gt; +10 ; +2 contre les pouvoirs des aberrations et des vases
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#ESQUIVEINSTINCTIVE&quot; title=&quot;Le barbare&quot;&gt;esquive instinctive&lt;/a&gt; ; &lt;b&gt;R&#233;sistance&lt;/b&gt; feu 10
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 15 m (10 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;grande hache +1&lt;/i&gt;, +15/+10 (1d12+8/&#215;3) et &lt;i&gt;morsure +1&lt;/i&gt;, +10 (1d4+4) ou &lt;i&gt;morsure +1&lt;/i&gt;, +15 (1d4+8) et 2 griffes +1, +15 (1d4+8)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#192; distance&lt;/b&gt; javeline, +7 (1d6+7)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#FORMEANIMALE&quot; title=&quot;Le druide&quot;&gt;forme animale&lt;/a&gt; 1/jour (peut prendre une forme de vase mais pas de forme de plante), &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#POUVOIRDERAGE&quot; title=&quot;Le barbare&quot;&gt;pouvoir de rage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#MOMENTDELUCIDITE&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;moment de lucidit&#233;&lt;/a&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGEDEBERSERKER&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; (7 rounds/jour), &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Feu.html&quot; title=&quot;Domaine du Feu&quot;&gt;trait de feu&lt;/a&gt; (1d6+3 feu, 6/jour)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Sorts de druide pr&#233;par&#233;s&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; +6 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +9)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
3e - &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu.html&quot; title=&quot;Boule de feu&quot;&gt;boule de feu&lt;/a&gt;&lt;/i&gt; (DD 16), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-De-Crocs.html&quot; title=&quot;Nu&#233;e de crocs&quot;&gt;nu&#233;e de crocs&lt;/a&gt;&lt;/i&gt; (DD 16)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
2e – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Appel-Des-Pierres.html&quot; title=&quot;Appel des pierres&quot;&gt;appel des pierres&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flammes.html&quot; title=&quot;Flammes&quot;&gt;flammes&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-De-Taureau.html&quot; title=&quot;Force de taureau&quot;&gt;force de taureau&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-D&#233;corce.html&quot; title=&quot;Peau d&amp;#39;&#233;corce&quot;&gt;peau d’&#233;corce&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1e – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Pas.html&quot; title=&quot;Grand pas&quot;&gt;grand pas&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt; (DD 14), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Passage-Sans-Traces.html&quot; title=&quot;Passage sans trace&quot;&gt;passage sans traces&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt; (2)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
0 (&#224; volont&#233;) – &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Deau.html&quot; title=&quot;Cr&#233;ation d&amp;#39;eau&quot;&gt;cr&#233;ation d’eau&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orientation.html&quot; title=&quot;Orientation&quot;&gt;orientation&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;paration.html&quot; title=&quot;R&#233;paration&quot;&gt;r&#233;paration&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;D&lt;/b&gt; sort de domaine ; &lt;b&gt;Domaine&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Feu.html&quot; title=&quot;Domaine du Feu&quot;&gt;Feu&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Tactique&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Avant le combat.&lt;/b&gt; Le chef de clan lance &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-De-Taureau.html&quot; title=&quot;Force de taureau&quot;&gt;force de taureau&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt; sur lui-m&#234;me et sur un alli&#233;, puis il lance &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-D&#233;corce.html&quot; title=&quot;Peau d&amp;#39;&#233;corce&quot;&gt;peau d’&#233;corce&lt;/a&gt;&lt;/i&gt; sur lui-m&#234;me.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pendant le combat.&lt;/b&gt; Lorsque ses ennemis sont encore &#224; port&#233;e, le chef de clan lance &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-De-Crocs.html&quot; title=&quot;Nu&#233;e de crocs&quot;&gt;nu&#233;e de crocs&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Appel-Des-Pierres.html&quot; title=&quot;Appel des pierres&quot;&gt;appel des pierres&lt;/a&gt;&lt;/i&gt; et d’autres sorts d’attaque. S’il est accul&#233; au corps &#224; corps, il entre en &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGEDEBERSERKER&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; et attaque avec sa grande hache.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Statistiques de base.&lt;/b&gt; Quand il n’est pas en &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGEDEBERSERKER&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; et ne b&#233;n&#233;ficie pas de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-D&#233;corce.html&quot; title=&quot;Peau d&amp;#39;&#233;corce&quot;&gt;peau d’&#233;corce&lt;/a&gt;&lt;/i&gt;, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Force-De-Taureau.html&quot; title=&quot;Force de taureau&quot;&gt;force de taureau&lt;/a&gt;&lt;/i&gt; et de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Morsure-Magique-Supr&#234;me.html&quot; title=&quot;Morsure magique supr&#234;me&quot;&gt;morsure magique supr&#234;me&lt;/a&gt;&lt;/i&gt;supr&#234;me, le chef de clan poss&#232;de les statistiques suivantes : &lt;b&gt;CA&lt;/b&gt; 20, contact 13, pris au d&#233;pourvu 20 ; &lt;b&gt;pv &lt;/b&gt;84 ; &lt;b&gt;Vig &lt;/b&gt;+12, &lt;b&gt;Vol &lt;/b&gt;+8 ; &lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;grande hache +1&lt;/i&gt;, +13/+8 (1d12+6/&#215;3) et morsure, +7 (1d4+2) ou morsure, +12 (1d4+5) et 2 griffes, +12 (1d4+5) ; &lt;b&gt;&#192;
distance&lt;/b&gt; javeline, +7 (1d6+7) ; &lt;b&gt;For &lt;/b&gt;16, &lt;b&gt;Con &lt;/b&gt;13 ; &lt;b&gt;BMO &lt;/b&gt;+12, &lt;b&gt;DMD &lt;/b&gt;22.
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 24, &lt;b&gt;Dex&lt;/b&gt; 11, &lt;b&gt;Con&lt;/b&gt; 17, &lt;b&gt;Int&lt;/b&gt; 10, &lt;b&gt;Sag&lt;/b&gt; 16, &lt;b&gt;Cha&lt;/b&gt; 13
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +7, &lt;b&gt;BMO&lt;/b&gt; +14, &lt;b&gt;DMD&lt;/b&gt; 22
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magie-De-Guerre.html&quot; title=&quot;Magie de guerre&quot;&gt;Magie de guerre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Robustesse.html&quot; title=&quot;Robustesse&quot;&gt;Robustesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (exploration souterraine) +2, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) +6, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +7, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +3, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +10, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +12, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +9, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +5
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; draconique, druidique
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;arpenteur des tunnels&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#DEPLACEMENTACCELERE&quot; title=&quot;Le barbare&quot;&gt;d&#233;placement acc&#233;l&#233;r&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#EMPATHIESAUVAGE&quot; title=&quot;Le druide&quot;&gt;empathie sauvage&lt;/a&gt; +7 (influence les vases, pas les cr&#233;atures magiques, &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#INSTINCTNATUREL&quot; title=&quot;Le druide&quot;&gt;instinct naturel&lt;/a&gt;, lien avec la nature (&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Feu.html&quot; title=&quot;Domaine du Feu&quot;&gt;domaine du Feu&lt;/a&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potions&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Mod&#233;r&#233;s.html&quot; title=&quot;Soins mod&#233;r&#233;s&quot;&gt;soins mod&#233;r&#233;s&lt;/a&gt;&lt;/i&gt; (2), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parchemins-Magiques.html&quot; title=&quot;Les parchemins magiques&quot;&gt;parchemin&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Fusion-Dans-La-Pierre.html&quot; title=&quot;Fusion dans la pierre&quot;&gt;fusion avec la pierre&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Chemise-De-Mailles-(Armure).html&quot; title=&quot;Chemise de mailles&quot;&gt;chemise de mailles de ma&#238;tre&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grande-Hache-(Arme).html&quot; title=&quot;Grande hache&quot;&gt;grande hache +1&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Javeline-(Arme).html&quot; title=&quot;Javeline&quot;&gt;javelines&lt;/a&gt; (5), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ceinturon-De-Dext&#233;rit&#233;-Du-Chat.html&quot; title=&quot;Ceinturon de dext&#233;rit&#233; du chat&quot;&gt;ceinturon de dext&#233;rit&#233; du chat +2&lt;/a&gt;&lt;/i&gt;, sac de pierres pr&#233;cieuses (d’une valeur totale de 200 po), 50 po
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
